def _canon(h):
    best = None
    for perm in itertools.permutations(SUITS):
        m = dict(zip(SUITS, perm))
        cs = sorted(((_RI[c[0]], m[c[1]]) for c in h), reverse=True)
        key = tuple(cs)
        if best is None or key < best:
            best = key
    return "".join(RANKS[r] + s for r, s in best)


def _build():
    deck = [r + s for r in RANKS for s in SUITS]
    out = {}
    for h in itertools.combinations(deck, 3):
        row = CLASSES.get(_canon(h))
        if row is not None:
            out[tuple(sorted(h))] = row
    return out


# ~22,100 entries. Built once at import; never touched in act().
TABLE = _build()


def _norm(c):
    try:
        return c[0].upper() + c[1].lower()
    except Exception:
        return None


def equity(cards, n_opponents):
    """Equity vs n opponents, or None if the holding cannot be looked up."""
    try:
        if len(cards) != 3:
            return None
        key = tuple(sorted(_norm(c) for c in cards))
        row = TABLE.get(key)
        if row is None:
            return None
        n = 1 if n_opponents < 1 else (7 if n_opponents > 7 else int(n_opponents))
        return row[n - 1]
    except Exception:
        return None
